import { GoogleGenAI, Type } from "@google/genai";
import { FormData, BBNTData } from "../types";

export interface ExtractionResult {
  bm02: FormData;
  bbnt: BBNTData;
}

export async function extractDataFromFile(fileBase64: string, mimeType: string): Promise<ExtractionResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `Bạn là một trợ lý AI cao cấp chuyên về nghiệp vụ quản lý vật tư và hồ sơ thi công tại Việt Nam. 
  Nhiệm vụ của bạn là đọc tệp đính kèm (PDF hoặc Ảnh) và trích xuất thông tin chính xác cho hai biểu mẫu sau:

  1. BIỂU MẪU BM02 (TỜ TRÌNH PHÊ DUYỆT KINH PHÍ):
     - Title: Tạo tiêu đề theo mẫu "V/v: Phê duyệt dự trù kinh phí mua vật tư thi công: [Nội dung công việc] [Vị trí]". Lưu ý: [Vị trí] bao gồm số căn, số lô, tên dự án. KHÔNG lặp lại thông tin nếu nội dung công việc đã chứa vị trí. Loại bỏ địa danh cấp hành chính (Quận, Phường).
     - ProposingCompany: Tên công ty/đơn vị đề xuất (thường nằm ở đầu văn bản hoặc trong dấu mộc).
     - Date: Chuyển đổi về định dạng "ngày [dd] tháng [mm] năm [yyyy]". Ví dụ: ngày 20 tháng 05 năm 2025.
     - Items: Trích xuất bảng vật tư gồm: Tên, Đơn vị tính, Số lượng, Đơn giá. Nếu không có đơn giá, hãy để mặc định là 0.

  2. BIỂU MẪU BM03.2 (BIÊN BẢN NGHIỆM THU):
     - Project: Tên công trình.
     - Category: Hạng mục thi công.
     - Address: Địa điểm thi công cụ thể.
     - Parties: Xác định Bên Giao (Công ty, Đại diện, Chức vụ) và Bên Nhận (Thường là Becamex).
     - Timeline: Thời gian bắt đầu và kết thúc (Giờ và Ngày).
     - Items: Bảng khối lượng nghiệm thu.

  YÊU CẦU QUAN TRỌNG: 
  - Trả về kết quả dưới dạng JSON thuần túy.
  - Luôn đảm bảo tính nhất quán giữa hai biểu mẫu nếu chúng cùng thuộc một hồ sơ.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [
      {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: fileBase64,
            },
          },
          { text: prompt },
        ],
      },
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          bm02: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              proposingCompany: { type: Type.STRING },
              date: { type: Type.STRING },
              grounds: { type: Type.ARRAY, items: { type: Type.STRING } },
              items: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    name: { type: Type.STRING },
                    unit: { type: Type.STRING },
                    quantity: { type: Type.NUMBER },
                    unitPrice: { type: Type.NUMBER }
                  }
                }
              }
            }
          },
          bbnt: {
            type: Type.OBJECT,
            properties: {
              location: { type: Type.STRING },
              date: { type: Type.STRING },
              project: { type: Type.STRING },
              category: { type: Type.STRING },
              address: { type: Type.STRING },
              senderCompany: { type: Type.STRING },
              senderRepresentative: { type: Type.STRING },
              senderPosition: { type: Type.STRING },
              startTime: { type: Type.STRING },
              startDate: { type: Type.STRING },
              endTime: { type: Type.STRING },
              endDate: { type: Type.STRING },
              grounds: { type: Type.ARRAY, items: { type: Type.STRING } },
              receiverList: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    salutation: { type: Type.STRING },
                    name: { type: Type.STRING },
                    position: { type: Type.STRING }
                  }
                }
              },
              items: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    description: { type: Type.STRING },
                    unit: { type: Type.STRING },
                    requestedQty: { type: Type.NUMBER },
                    acceptedQty: { type: Type.NUMBER }
                  }
                }
              }
            }
          }
        }
      },
    },
  });

  const rawData = JSON.parse(response.text);
  const proposingCo = rawData.bm02?.proposingCompany || '...';

  const bm02: FormData = {
    docNumber: 'QTMH-BM02',
    title: rawData.bm02?.title || 'Phê duyệt dự trù kinh phí mua vật tư thi công...',
    date: rawData.bm02?.date || 'ngày ... tháng ... năm 2025',
    location: 'Tp. Hồ Chí Minh',
    recipients: ['Hội Đồng Thành Viên', 'BGĐ Công ty TNHH MTV Thương Mại Becamex'],
    grounds: rawData.bm02?.grounds?.length ? rawData.bm02.grounds : [
      `Căn cứ Phiếu đề nghị về việc cung cấp vật tư của Công ty ${proposingCo}`,
      'Căn cứ Báo giá của Công ty CP KD và PT Bình Dương - Xí Nghiệp Bê Tông Trộn Sẵn Mỹ Phước'
    ],
    items: (rawData.bm02?.items || []).map((it: any, idx: number) => ({
      id: Math.random().toString(36).substr(2, 9),
      stt: idx + 1,
      name: it.name || '',
      unit: it.unit || 'm3',
      quantity: it.quantity || 0,
      unitPrice: it.unitPrice || 0,
      total: (it.quantity || 0) * (it.unitPrice || 0),
      note: ''
    })),
    totalAmount: (rawData.bm02?.items || []).reduce((s: number, it: any) => s + (it.quantity * it.unitPrice || 0), 0),
    proposingCompany: proposingCo
  };

  const bbnt: BBNTData = {
    docNumber: 'QTMH-BM03.2',
    location: rawData.bbnt?.location || 'Bình Dương',
    date: rawData.bbnt?.date || 'ngày ... tháng ... năm 2025',
    project: rawData.bbnt?.project || '',
    category: rawData.bbnt?.category || '',
    address: rawData.bbnt?.address || '',
    senderCompany: rawData.bbnt?.senderCompany || proposingCo,
    senderRepresentative: rawData.bbnt?.senderRepresentative || '',
    senderPosition: rawData.bbnt?.senderPosition || '',
    receiverCompany: 'Công ty TNHH MTV Thương Mại Becamex',
    receiverList: rawData.bbnt?.receiverList?.length ? rawData.bbnt.receiverList : [
      { name: 'Nguyễn Xuân Nam', position: 'Phó Giám đốc', salutation: 'Ông' },
      { name: 'Lương Thị Ngọc Trinh', position: 'Kế toán trưởng', salutation: 'Bà' },
      { name: 'Đỗ Thế Viễn', position: 'Phó phòng KT', salutation: 'Ông' },
      { name: 'Lê Minh Chánh', position: 'NV', salutation: 'Ông' },
      { name: 'Trần Nam Anh', position: 'NV', salutation: 'Ông' }
    ],
    startTime: rawData.bbnt?.startTime || '',
    startDate: rawData.bbnt?.startDate || '',
    endTime: rawData.bbnt?.endTime || '',
    endDate: rawData.bbnt?.endDate || '',
    locationDetail: 'Tại: Công trình',
    grounds: rawData.bbnt?.grounds || [],
    items: (rawData.bbnt?.items || []).map((it: any, idx: number) => ({
      id: Math.random().toString(36).substr(2, 9),
      stt: idx + 1,
      description: it.description || '',
      unit: it.unit || '',
      requestedQty: it.requestedQty || 0,
      acceptedQty: it.acceptedQty || 0,
      note: ''
    }))
  };

  return { bm02, bbnt };
}

import React, { useState } from 'react';
import { 
  Upload, 
  FileText, 
  Download, 
  Loader2, 
  Plus, 
  Trash2, 
  AlertCircle, 
  CheckCircle2, 
  LayoutGrid, 
  FileCheck,
  ChevronRight,
  RefreshCcw,
  FileCode
} from 'lucide-react';
import { extractDataFromFile } from './services/geminiService';
import { exportToDocx, exportBBNTToDocx } from './services/docxExport';
import { FormData, BBNTData, LineItem, BBNTItem } from './types';

const INITIAL_BM02: FormData = {
  docNumber: 'QTMH-BM02',
  title: 'Phê duyệt dự trù kinh phí mua vật tư thi công...',
  date: 'ngày ... tháng ... năm 2025',
  location: 'Tp. Hồ Chí Minh',
  recipients: ['Hội Đồng Thành Viên', 'BGĐ Công ty TNHH MTV Thương Mại Becamex'],
  grounds: [
    'Căn cứ Phiếu đề nghị về việc cung cấp vật tư của Công ty ...',
    'Căn cứ Báo giá của Công ty CP KD và PT Bình Dương - Xí Nghiệp Bê Tông Trộn Sẵn Mỹ Phước'
  ],
  items: [],
  totalAmount: 0,
  proposingCompany: ''
};

const INITIAL_BM03: BBNTData = {
  docNumber: 'QTMH-BM03.2',
  location: 'Bình Dương',
  date: 'ngày ... tháng ... năm 2025',
  project: '',
  category: '',
  address: '',
  senderCompany: '',
  senderRepresentative: '',
  senderPosition: '',
  receiverCompany: 'Công ty TNHH MTV Thương Mại Becamex',
  receiverList: [],
  startTime: '',
  startDate: '',
  endTime: '',
  endDate: '',
  locationDetail: 'Tại: Công trình',
  grounds: [],
  items: []
};

type TabType = 'BM02' | 'BBNT';

export default function App() {
  const [activeTab, setActiveTab] = useState<TabType>('BM02');
  const [bm02Data, setBm02Data] = useState<FormData>(INITIAL_BM02);
  const [bbntData, setBbntData] = useState<BBNTData>(INITIAL_BM03);
  const [isProcessing, setIsProcessing] = useState(false);
  const [hasData, setHasData] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [currentFileName, setCurrentFileName] = useState<string | null>(null);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);
    setError(null);
    setCurrentFileName(file.name);

    try {
      const reader = new FileReader();
      reader.onload = async () => {
        const mimeType = file.type;
        const base64 = (reader.result as string).split(',')[1];
        const result = await extractDataFromFile(base64, mimeType);

        const originalName = file.name.replace(/\.[^/.]+$/, "");

        setBm02Data({ ...result.bm02, originalFileName: originalName });
        setBbntData({ ...result.bbnt, originalFileName: originalName });

        setIsProcessing(false);
        setHasData(true);
      };
      reader.readAsDataURL(file);
    } catch (err: any) {
      setError("Không thể trích xuất dữ liệu. Vui lòng kiểm tra lại file PDF/Ảnh.");
      setIsProcessing(false);
    }
  };

  const handleExport = () => {
    if (activeTab === 'BM02') {
      exportToDocx(bm02Data);
    } else {
      exportBBNTToDocx(bbntData);
    }
  };

  const updateBM02Item = (id: string, field: keyof LineItem, value: any) => {
    setBm02Data(prev => {
      const newItems = prev.items.map(item => {
        if (item.id === id) {
          const updated = { ...item, [field]: value };
          if (field === 'quantity' || field === 'unitPrice') {
            updated.total = (updated.quantity || 0) * (updated.unitPrice || 0);
          }
          return updated;
        }
        return item;
      });
      const newTotal = newItems.reduce((sum, item) => sum + (item.total || 0), 0);
      return { ...prev, items: newItems, totalAmount: newTotal };
    });
  };

  const addBM02Item = () => {
    const newItem: LineItem = {
      id: Math.random().toString(36).substr(2, 9),
      stt: bm02Data.items.length + 1,
      name: '',
      unit: 'm3',
      quantity: 0,
      unitPrice: 0,
      total: 0,
      note: ''
    };
    setBm02Data(prev => ({ ...prev, items: [...prev.items, newItem] }));
  };

  const deleteBM02Item = (id: string) => {
    setBm02Data(prev => {
      const newItems = prev.items.filter(item => item.id !== id).map((it, idx) => ({...it, stt: idx + 1}));
      const newTotal = newItems.reduce((sum, item) => sum + (item.total || 0), 0);
      return { ...prev, items: newItems, totalAmount: newTotal };
    });
  };

  return (
    <div className="min-h-screen bg-[#F0F2F5] flex flex-col font-sans">
      {/* Header Bar */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-40 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="bg-indigo-600 p-2 rounded-lg shadow-indigo-200 shadow-lg text-white">
              <FileCode size={24} />
            </div>
            <div>
              <h1 className="font-bold text-slate-900 text-lg leading-tight">BTI AutoDoc AI</h1>
              <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Hệ thống xử lý hồ sơ thông minh</p>
            </div>
          </div>

          <div className="flex items-center gap-3">
            {!hasData ? (
              <label className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 text-white rounded-full cursor-pointer hover:bg-indigo-700 transition-all text-sm font-semibold shadow-md hover:shadow-lg active:scale-95">
                <Upload size={18} />
                Tải lên hồ sơ nguồn
                <input type="file" className="hidden" accept=".pdf,image/*" onChange={handleFileUpload} />
              </label>
            ) : (
              <div className="flex gap-2">
                 <label className="flex items-center gap-2 px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-full border border-slate-200 cursor-pointer transition-all text-sm font-semibold">
                  <RefreshCcw size={16} />
                  Thay đổi file
                  <input type="file" className="hidden" accept=".pdf,image/*" onChange={handleFileUpload} />
                </label>
                <button 
                  onClick={handleExport}
                  className="flex items-center gap-2 px-5 py-2.5 bg-green-600 text-white rounded-full hover:bg-green-700 transition-all text-sm font-semibold shadow-md active:scale-95"
                >
                  <Download size={18} />
                  Xuất bản {activeTab}
                </button>
              </div>
            )}
          </div>
        </div>

        {/* Workflow Steps Indicator */}
        <div className="max-w-7xl mx-auto px-6 py-2 flex items-center gap-4 text-xs font-bold text-slate-400">
           <div className={`flex items-center gap-1 ${hasData ? 'text-green-600' : 'text-indigo-600'}`}>
             <span className={`w-5 h-5 flex items-center justify-center rounded-full border ${hasData ? 'bg-green-600 border-green-600 text-white' : 'border-indigo-600 text-indigo-600'}`}>1</span>
             Tải PDF/Ảnh
           </div>
           <ChevronRight size={14} />
           <div className={`flex items-center gap-1 ${hasData ? 'text-indigo-600' : ''}`}>
             <span className={`w-5 h-5 flex items-center justify-center rounded-full border ${hasData ? 'border-indigo-600 text-indigo-600' : 'border-slate-300'}`}>2</span>
             Kiểm tra dữ liệu
           </div>
           <ChevronRight size={14} />
           <div className="flex items-center gap-1">
             <span className="w-5 h-5 flex items-center justify-center rounded-full border border-slate-300">3</span>
             Xuất file Word
           </div>
        </div>
      </header>

      {/* Main Layout */}
      <div className="flex-1 flex overflow-hidden">
        {/* Sidebar for Navigation / Status */}
        <aside className="w-64 bg-white border-r border-slate-200 hidden lg:flex flex-col p-4 space-y-4">
          <div className="p-4 bg-slate-50 rounded-xl border border-slate-100">
             <h3 className="text-xs font-bold text-slate-400 uppercase mb-2">Đang xử lý</h3>
             {currentFileName ? (
               <div className="flex items-start gap-2">
                 <FileText className="text-indigo-600 shrink-0" size={18} />
                 <span className="text-sm font-medium text-slate-700 break-all">{currentFileName}</span>
               </div>
             ) : (
               <p className="text-sm text-slate-400 italic">Chưa có tệp nào...</p>
             )}
          </div>

          <nav className="space-y-1">
            <button 
              onClick={() => setActiveTab('BM02')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-bold transition-all ${activeTab === 'BM02' ? 'bg-indigo-50 text-indigo-700 border border-indigo-100' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              <LayoutGrid size={18} />
              Tờ trình BM02
            </button>
            <button 
              onClick={() => setActiveTab('BBNT')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-bold transition-all ${activeTab === 'BBNT' ? 'bg-indigo-50 text-indigo-700 border border-indigo-100' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              <FileCheck size={18} />
              Nghiệm thu BM03.2
            </button>
          </nav>

          <div className="mt-auto p-4 bg-yellow-50 rounded-xl border border-yellow-100">
            <h4 className="text-xs font-bold text-yellow-700 flex items-center gap-1 mb-1">
              <AlertCircle size={14} /> Ghi chú
            </h4>
            <p className="text-[11px] text-yellow-600 leading-relaxed">
              Dữ liệu được trích xuất bằng AI. Vui lòng kiểm tra lại các trường chữ màu đỏ trước khi xuất file.
            </p>
          </div>
        </aside>

        {/* Content Area */}
        <main className="flex-1 overflow-y-auto bg-[#F8FAFC] p-4 md:p-8">
          {isProcessing && (
            <div className="absolute inset-0 bg-white/80 backdrop-blur-sm z-50 flex flex-col items-center justify-center">
              <div className="relative">
                <div className="w-16 h-16 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center">
                  <FileText className="text-indigo-600 animate-bounce" size={24} />
                </div>
              </div>
              <p className="mt-6 font-bold text-slate-800 text-lg">AI Đang phân tích hồ sơ...</p>
              <p className="text-slate-500 text-sm mt-2">Vui lòng đợi trong giây lát</p>
            </div>
          )}

          {!hasData && !isProcessing && (
            <div className="h-full flex flex-col items-center justify-center">
              <div className="bg-white p-12 rounded-3xl shadow-xl border border-slate-100 text-center max-w-md">
                 <div className="w-20 h-20 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center mx-auto mb-6">
                    <Upload size={40} />
                 </div>
                 <h2 className="text-2xl font-bold text-slate-900 mb-2">Bắt đầu ngay</h2>
                 <p className="text-slate-500 mb-8">Tải lên tệp PDF hoặc ảnh chụp hồ sơ đề nghị để AI tự động điền vào biểu mẫu mẫu của công ty.</p>
                 <label className="inline-flex items-center gap-2 px-8 py-4 bg-indigo-600 text-white rounded-2xl cursor-pointer hover:bg-indigo-700 transition-all font-bold shadow-lg shadow-indigo-200">
                    Tải file lên
                    <input type="file" className="hidden" accept=".pdf,image/*" onChange={handleFileUpload} />
                 </label>
              </div>
            </div>
          )}

          {error && (
            <div className="max-w-4xl mx-auto mb-6 flex items-center gap-3 p-4 bg-red-50 text-red-700 border border-red-200 rounded-xl">
              <AlertCircle size={20} />
              <p className="font-semibold">{error}</p>
            </div>
          )}

          {hasData && (
            <div className="max-w-[850px] mx-auto">
              <div className="mb-4 flex justify-between items-center lg:hidden">
                <div className="flex gap-2">
                  <button onClick={() => setActiveTab('BM02')} className={`px-4 py-2 rounded-lg text-sm font-bold ${activeTab === 'BM02' ? 'bg-indigo-600 text-white' : 'bg-white text-slate-600'}`}>BM02</button>
                  <button onClick={() => setActiveTab('BBNT')} className={`px-4 py-2 rounded-lg text-sm font-bold ${activeTab === 'BBNT' ? 'bg-indigo-600 text-white' : 'bg-white text-slate-600'}`}>BM03.2</button>
                </div>
              </div>

              {/* Form Render */}
              <div className="bg-white shadow-2xl rounded-sm border border-slate-300 document-font p-12 md:p-16 space-y-8 min-h-[1100px] text-black relative">
                {activeTab === 'BM02' ? (
                  <>
                    {/* BM02 Specific Header */}
                    <div className="grid grid-cols-[1.2fr_3fr_1fr] border border-black">
                      <div className="border-r border-black p-4 flex items-center justify-center">
                        <div className="bti-logo-container">
                          <div className="bti-box"><span className="bti-letter">B</span></div>
                          <div className="bti-box"><span className="bti-letter">T</span></div>
                          <div className="bti-box"><span className="bti-letter">I</span></div>
                        </div>
                      </div>
                      <div className="border-r border-black p-4 flex flex-col items-center justify-center text-center">
                        <div className="font-bold text-xl mb-1 uppercase">Tờ trình</div>
                        <textarea 
                          className="w-full text-center font-bold text-red-600 bg-transparent border-none focus:ring-0 p-0 text-[13pt] resize-none overflow-hidden"
                          value={bm02Data.title}
                          rows={2}
                          onChange={(e) => setBm02Data({...bm02Data, title: e.target.value})}
                        />
                      </div>
                      <div className="p-2 flex items-center justify-center font-bold text-xs uppercase">QTMH-BM02</div>
                    </div>

                    <div className="text-right italic text-red-600 flex justify-end gap-1">
                        <input className="bg-transparent border-none text-right focus:ring-0 p-0 italic w-32" value={bm02Data.location} onChange={(e) => setBm02Data({...bm02Data, location: e.target.value})} />, 
                        <input className="bg-transparent border-none text-left focus:ring-0 p-0 italic w-64" value={bm02Data.date} onChange={(e) => setBm02Data({...bm02Data, date: e.target.value})} />
                    </div>

                    <div className="space-y-4">
                      <div className="flex gap-4">
                        <span className="font-bold min-w-[80px]">Kính gửi:</span>
                        <div className="flex-1 space-y-1 font-bold">
                          {bm02Data.recipients.map((r, i) => (
                            <div key={i} className="flex gap-2 group">
                              <span>-</span>
                              <input className="bg-transparent border-none focus:ring-0 p-0 w-full" value={r} onChange={(e) => {
                                  const newRec = [...bm02Data.recipients];
