import { GoogleGenAI, Type } from "@google/genai";
import { FormData, BBNTData } from "../types";

export interface ExtractionResult {
  bm02: FormData;
  bbnt: BBNTData;
}

export async function extractDataFromFile(fileBase64: string, mimeType: string): Promise<ExtractionResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `Bạn là một chuyên gia trích xuất dữ liệu hành chính từ tài liệu xây dựng Việt Nam.
  Hãy phân tích kỹ tệp tin đính kèm và thực hiện trích xuất dữ liệu cho HAI biểu mẫu:

  1. BIỂU MẪU BM02 (TỜ TRÌNH PHÊ DUYỆT KINH PHÍ):
     - Title: "V/v: Phê duyệt dự trù kinh phí mua vật tư thi công: [Nội dung công việc] [Số Căn] [Số Lô] [Tên Dự án]".
     - Quy tắc Title quan trọng: Ghép nội dung công việc và vị trí (Căn, Lô, Khu) thành một chuỗi logic, KHÔNG lặp lại thông tin. Nếu trong "Nội dung công việc" đã có "Căn 56" thì phía sau KHÔNG được thêm "Căn 56" nữa. Loại bỏ thông tin Phường, Quận, Tỉnh.
     - ProposingCompany: Trích xuất tên công ty gửi đề nghị (Ví dụ: TIẾN ĐOÀN).
     - Date: Trích xuất ngày tháng năm và trả về ĐÚNG định dạng: "ngày [dd] tháng [mm] năm [yyyy]" (ví dụ: ngày 17 tháng 11 năm 2025). Tuyệt đối không dùng dấu gạch chéo (/).
     - Location: Luôn trả về là "Tp. Hồ Chí Minh" trừ khi có yêu cầu khác.
     - Grounds (Căn cứ): Trả về danh sách gồm ĐÚNG 2 căn cứ sau (thay [Tên Công ty] bằng ProposingCompany):
        1. "Căn cứ Phiếu đề nghị về việc cung cấp vật tư của Công ty [Tên Công ty]"
        2. "Căn cứ Báo giá của Công ty CP KD và PT Bình Dương - Xí Nghiệp Bê Tông Trộn Sẵn Mỹ Phước"
     - Items: Danh sách vật tư (Tên, Đvt, SL, Đơn giá).

  2. BIỂU MẪU BM03.2 (BIÊN BẢN NGHIỆM THU VÀ BÀN GIAO):
     - Date: Trích xuất ngày tháng năm và trả về ĐÚNG định dạng: "ngày [dd] tháng [mm] năm [yyyy]".
     - Location: Luôn trả về là "Tp. Hồ Chí Minh".
     - Project (Công trình), Category (Hạng mục), Address (Địa điểm).
     - Bên Giao: Công ty, Người đại diện, Chức vụ.
     - Bên Nhận: Công ty (Becamex), danh sách người tham gia (Ông/Bà, Tên, Chức vụ).
     - Thời gian: Giờ và Ngày bắt đầu/kết thúc (Ngày cũng phải định dạng ngày... tháng... năm...).
     - Items: Bảng khối lượng (Diễn giải, ĐVT, SL yêu cầu, SL nghiệm thu).

  Yêu cầu định dạng ngày tháng: Nếu thấy 26/11/2025, phải chuyển thành "ngày 26 tháng 11 năm 2025".
  Trả về JSON theo cấu trúc quy định.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [
      {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: fileBase64,
            },
          },
          { text: prompt },
        ],
      },
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          bm02: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              proposingCompany: { type: Type.STRING },
              date: { type: Type.STRING },
              location: { type: Type.STRING },
              grounds: { type: Type.ARRAY, items: { type: Type.STRING } },
              items: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    name: { type: Type.STRING },
                    unit: { type: Type.STRING },
                    quantity: { type: Type.NUMBER },
                    unitPrice: { type: Type.NUMBER }
                  }
                }
              }
            }
          },
          bbnt: {
            type: Type.OBJECT,
            properties: {
              location: { type: Type.STRING },
              date: { type: Type.STRING },
              project: { type: Type.STRING },
              category: { type: Type.STRING },
              address: { type: Type.STRING },
              senderCompany: { type: Type.STRING },
              senderRepresentative: { type: Type.STRING },
              senderPosition: { type: Type.STRING },
              startTime: { type: Type.STRING },
              startDate: { type: Type.STRING },
              endTime: { type: Type.STRING },
              endDate: { type: Type.STRING },
              grounds: { type: Type.ARRAY, items: { type: Type.STRING } },
              receiverList: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    salutation: { type: Type.STRING },
                    name: { type: Type.STRING },
                    position: { type: Type.STRING }
                  }
                }
              },
              items: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    description: { type: Type.STRING },
                    unit: { type: Type.STRING },
                    requestedQty: { type: Type.NUMBER },
                    acceptedQty: { type: Type.NUMBER }
                  }
                }
              }
            }
          }
        }
      },
    },
  });

  const rawData = JSON.parse(response.text);
  const proposingCo = rawData.bm02?.proposingCompany || '...';

  const bm02: FormData = {
    docNumber: 'QTMH-BM02',
    title: rawData.bm02?.title || 'Phê duyệt dự trù kinh phí mua vật tư thi công...',
    date: rawData.bm02?.date || 'ngày ... tháng ... năm 2025',
    location: rawData.bm02?.location || 'Tp. Hồ Chí Minh',
    recipients: ['Hội Đồng Thành Viên', 'BGĐ Công ty TNHH MTV Thương Mại Becamex'],
    grounds: rawData.bm02?.grounds && rawData.bm02.grounds.length > 0 ? rawData.bm02.grounds : [
      `Căn cứ Phiếu đề nghị về việc cung cấp vật tư của Công ty ${proposingCo}`,
      'Căn cứ Báo giá của Công ty CP KD và PT Bình Dương - Xí Nghiệp Bê Tông Trộn Sẵn Mỹ Phước'
    ],
    items: (rawData.bm02?.items || []).map((it: any, idx: number) => ({
      id: Math.random().toString(36).substr(2, 9),
      stt: idx + 1,
      name: it.name,
      unit: it.unit || 'm3',
      quantity: it.quantity || 0,
      unitPrice: it.unitPrice || 0,
      total: (it.quantity || 0) * (it.unitPrice || 0),
      note: ''
    })),
    totalAmount: (rawData.bm02?.items || []).reduce((s: number, it: any) => s + (it.quantity * it.unitPrice || 0), 0),
    proposingCompany: proposingCo
  };

  const bbnt: BBNTData = {
    docNumber: 'QTMH-BM03.2',
    location: rawData.bbnt?.location || 'Tp. Hồ Chí Minh',
    date: rawData.bbnt?.date || 'ngày ... tháng ... năm 2025',
    project: rawData.bbnt?.project || '',
    category: rawData.bbnt?.category || '',
    address: rawData.bbnt?.address || '',
    senderCompany: rawData.bbnt?.senderCompany || proposingCo,
    senderRepresentative: rawData.bbnt?.senderRepresentative || '',
    senderPosition: rawData.bbnt?.senderPosition || '',
    receiverCompany: 'Công ty TNHH MTV Thương Mại Becamex',
    receiverList: rawData.bbnt?.receiverList?.length ? rawData.bbnt.receiverList : [
      { name: 'Nguyễn Xuân Nam', position: 'Phó Giám đốc', salutation: 'Ông' },
      { name: 'Lương Thị Ngọc Trinh', position: 'Kế toán trưởng', salutation: 'Bà' },
      { name: 'Đỗ Thế Viễn', position: 'Phó phòng KT', salutation: 'Ông' },
      { name: 'Lê Minh Chánh', position: 'NV', salutation: 'Ông' },
      { name: 'Trần Nam Anh', position: 'NV', salutation: 'Ông' }
    ],
    startTime: rawData.bbnt?.startTime || '',
    startDate: rawData.bbnt?.startDate || '',
    endTime: rawData.bbnt?.endTime || '',
    endDate: rawData.bbnt?.endDate || '',
    locationDetail: 'Tại: Công trình',
    grounds: rawData.bbnt?.grounds || [],
    items: (rawData.bbnt?.items || []).map((it: any, idx: number) => ({
      id: Math.random().toString(36).substr(2, 9),
      stt: idx + 1,
      description: it.description || '',
      unit: it.unit || '',
      requestedQty: it.requestedQty || 0,
      acceptedQty: it.acceptedQty || 0,
      note: ''
    }))
  };

  return { bm02, bbnt };
}

