type TabType = 'BM02' | 'BBNT';

export default function App() {
  const [activeTab, setActiveTab] = useState<TabType>('BM02');
  const [bm02Data, setBm02Data] = useState<FormData>(INITIAL_BM02);
  const [bbntData, setBbntData] = useState<BBNTData>(INITIAL_BM03);
  const [isProcessing, setIsProcessing] = useState(false);
  const [hasData, setHasData] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);
    setError(null);
    setHasData(false);

    try {
      const reader = new FileReader();
      reader.onload = async () => {
        const mimeType = file.type;
        const base64 = (reader.result as string).split(',')[1];
        const result = await extractDataFromFile(base64, mimeType);

        const originalName = file.name.replace(/\.[^/.]+$/, "");

        setBm02Data({ ...result.bm02, originalFileName: originalName });
        setBbntData({ ...result.bbnt, originalFileName: originalName });

        setIsProcessing(false);
        setHasData(true);
      };
      reader.readAsDataURL(file);
    } catch (err: any) {
      setError(err.message || "Đã có lỗi xảy ra.");
      setIsProcessing(false);
    }
  };

  const handleExport = () => {
    if (activeTab === 'BM02') {
      exportToDocx(bm02Data);
    } else {
      exportBBNTToDocx(bbntData);
    }
  };

  const updateBM02Item = (id: string, field: keyof LineItem, value: any) => {
    setBm02Data(prev => {
      const newItems = prev.items.map(item => {
        if (item.id === id) {
          const updated = { ...item, [field]: value };
          if (field === 'quantity' || field === 'unitPrice') {
            updated.total = (updated.quantity || 0) * (updated.unitPrice || 0);
          }
          return updated;
        }
        return item;
      });
      const newTotal = newItems.reduce((sum, item) => sum + (item.total || 0), 0);
      return { ...prev, items: newItems, totalAmount: newTotal };
    });
  };

  const addBM02Item = () => {
    const newItem: LineItem = {
      id: Math.random().toString(36).substr(2, 9),
      stt: bm02Data.items.length + 1,
      name: '',
      unit: 'm3',
      quantity: 0,
      unitPrice: 0,
      total: 0,
      note: ''
    };
    setBm02Data(prev => ({ ...prev, items: [...prev.items, newItem] }));
  };

  return (
    <div className="min-h-screen bg-slate-100 flex flex-col">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-6xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg text-white">
              <LayoutGrid size={22} />
            </div>
            <div>
              <h1 className="font-bold text-slate-900 leading-tight text-lg">BTI Smart Document</h1>
              <p className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">Trích xuất hồ sơ tự động</p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <label className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg cursor-pointer hover:bg-blue-700 transition-all text-sm font-semibold shadow-sm">
              <Upload size={16} />
              Tải hồ sơ PDF / Ảnh
              <input type="file" className="hidden" onChange={handleFileUpload} />
            </label>
            {hasData && (
              <button 
                onClick={handleExport}
                className="flex items-center gap-2 px-4 py-2 text-blue-600 hover:bg-blue-50 rounded-lg border border-blue-200 transition-all text-sm font-semibold"
              >
                <Download size={16} />
                Xuất file Word ({activeTab})
              </button>
            )}
          </div>
        </div>

        <div className="max-w-6xl mx-auto px-4 flex gap-8">
          <button 
            onClick={() => setActiveTab('BM02')}
            className={`py-3 text-sm font-bold border-b-2 transition-all ${activeTab === 'BM02' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
          >
            ĐN CCVT (BM02)
          </button>
