/**
 * Hàm hỗ trợ định dạng lại ngày tháng nếu có dạng DD/MM/YYYY
 */
function formatDate(dateStr: string): string {
  if (!dateStr) return "ngày ... tháng ... năm ...";
  // Nếu đã đúng định dạng "ngày... tháng... năm..." thì trả về luôn
  if (dateStr.includes("ngày") && dateStr.includes("tháng") && dateStr.includes("năm")) return dateStr;

  // Nếu có dạng DD/MM/YYYY hoặc tương tự
  const regex = /(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{4})/;
  const match = dateStr.match(regex);
  if (match) {
    const day = match[1].padStart(2, '0');
    const month = match[2].padStart(2, '0');
    const year = match[3];
    return `ngày ${day} tháng ${month} năm ${year}`;
  }

  return dateStr;
}

